import {mapState} from "vuex";
import contentInfo from './components/contentInfo';
import {
  allTopicApi,
  communityHeaderApi,
  communityListApi,
  communityStarApi,
  communityStatusApi,
  communityDownApi,
  communityVerifyApi,
  communityCommentApi
} from "@/api/community";

export default {
  name: "content",
  components: {
    contentInfo
  },
  data() {
    return {
      headeNum: [],
      topicList: [],
      starList: [
        {id: 1, name: '一星'},
        {id: 2, name: '二星'},
        {id: 3, name: '三星'},
        {id: 4, name: '四星'},
        {id: 5, name: '五星'}
      ],
      tableFrom: {
        page: 1,
        limit: 15,
        topic_id: "",
        star: "",
        content_type: "",
        keyword: "",
        is_verify: '1',
        type: ""
      },
      loading: false,
      columns: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "封面",
          slot: "image",
          width: 100,
        },
        {
          title: "内容标题",
          key: "title",
          minWidth: 150,
        },
        {
          title: "内容作者",
          key: "author",
          minWidth: 150,
        },
        {
          title: "内容类型",
          slot: "content_type",
          minWidth: 100,
        },
        {
          title: "推荐级别",
          slot: "star",
          minWidth: 200,
        },
        {
          title: "浏览量",
          key: "play_num",
          minWidth: 100,
        },
        {
          title: "点赞数",
          key: "like_num",
          minWidth: 100,
        },
        {
          title: "评论数",
          key: "comment_num",
          minWidth: 100,
        },
        {
          title: "发布时间",
          key: "add_time",
          minWidth: 150,
        },
        {
          title: "是否展示",
          slot: "status",
          minWidth: 100,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          align: "center",
          width: 200,
        }
      ],
      tableList: [],
      grid: {
        xl: 7,
        lg: 10,
        md: 12,
        sm: 24,
        xs: 24,
      },
      total: 0,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.allTopicList();
    this.communityHeader();
    this.getList();
  },
  methods: {
    // 用户发布内容审核
    verify(row) {
      this.$modalForm(communityVerifyApi(row.id)).then(() => {
        this.communityHeader();
        this.getList()
      });
    },
    // 话题列表；
    allTopicList() {
      allTopicApi().then(res => {
        this.topicList = res.data;
      }).catch(err => {
        this.$Message.error(err.msg);
      })
    },
    // 社区内容顶部header；
    communityHeader() {
      communityHeaderApi(this.tableFrom).then(res => {
        this.headeNum = res.data;
      }).catch(err => {
        this.$Message.error(err.msg);
      })
    },
    // 列表
    getList() {
      this.loading = true;
      communityListApi(this.tableFrom)
          .then((res) => {
            let data = res.data;
            this.tableList = data.list;
            this.total = res.data.count;
            this.loading = false;
          })
          .catch((err) => {
            this.loading = false;
            this.$Message.error(err.msg);
          });
    },
    // 表格搜索
    tableSearchs() {
      this.tableFrom.page = 1;
      this.getList();
    },
    reset() {
      this.tableFrom.topic_id = "";
      this.tableFrom.star = "";
      this.tableFrom.content_type = "";
      this.tableFrom.type = "";
      this.tableFrom.keyword = "";
      this.tableFrom.is_verify = "";
      this.tableFrom.page = 1;
      this.getList();
    },
    // 详情
    info(row) {
      this.$refs.content.modals = true
      this.$refs.content.getInfo(row.id)
      this.$refs.content.activeName = "detail";
      this.$refs.content.replyForm.community_id = row.id;
    },
    // 推荐指数
    star(row) {
      this.$modalForm(communityStarApi(row.id)).then(() => this.getList());
    },
    changeMenu(row, name, index) {
      switch (name) {
        case "1":
          this.$router.push({path: "/admin/content/community/addContent/" + row.id});
          break;
        case "2":
          this.$modalForm(communityCommentApi(row.id)).then(() => this.getList());
          break;
        case "3":
          this.$modalForm(communityDownApi(row.id)).then(() => {
            this.communityHeader();
            this.getList()
          });
          break;
        case "4":
          this.del(row, '删除内容', index);
          break;
        case "5":
          this.star(row);
          break;
      }
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/community/community/del/${row.id}`,
        method: "DELETE",
        ids: ""
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.tableList.splice(num, 1);
            if (!this.tableList.length) {
              this.tableFrom.page =
                  this.tableFrom.page == 1 ? 1 : this.tableFrom.page - 1;
            }
            this.communityHeader();
            this.getList();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    pageChange(index) {
      this.tableFrom.page = index;
      this.getList();
    },
    // 修改是否展示
    onchangeStatus(row) {
      let data = {
        id: row.id,
        status: row.status
      };
      communityStatusApi(data)
          .then((res) => {
            this.$Message.success(res.msg);
            this.getList()
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    }
  }
};
